import java.io.*;
import java.util.*;

public class Main {
    static final InputStream is = System.in;
    static final byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;

    static int rb() throws IOException {
        if (ptr == len) {
            len = is.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = rb();
        while (c != '-' && (c < '0' || c > '9')) c = rb();
        boolean neg = c == '-';
        if (neg) c = rb();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = rb();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }


    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        for (long v : a) {
            if (v == 0) {
                System.out.println(-1);
                return;
            }
        }
        // seenIn[prefix] = segment id that last produced this prefix sum (avoids clearing a set).
        HashMap<Long, Integer> seenIn = new HashMap<>(4 * n + 4);
        int segment = 0, answer = 0;
        long prefix = 0;
        seenIn.put(0L, segment);
        for (long v : a) {
            Integer last = seenIn.get(prefix + v);
            if (last != null && last == segment) {
                // A zero-sum segment would end here: insert a separator before v.
                answer++;
                segment++;
                prefix = 0;
                seenIn.put(0L, segment);
            }
            prefix += v;
            seenIn.put(prefix, segment);
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var reader = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	c, _ := reader.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = reader.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = reader.ReadByte()
	}
	n := 0
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = reader.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}


func main() {
	n := readInt()
	a := make([]int, n)
	for i := range a {
		a[i] = readInt()
	}
	for _, v := range a {
		if v == 0 {
			fmt.Println(-1)
			return
		}
	}
	// seenIn[prefix] = id (from 1) of the segment that last produced this prefix sum (avoids clearing a set).
	seenIn := make(map[int]int, 2*n+1)
	segment, answer, prefix := 1, 0, 0
	seenIn[0] = segment
	for _, v := range a {
		if seenIn[prefix+v] == segment {
			// A zero-sum segment would end here: insert a separator before v.
			answer++
			segment++
			prefix = 0
			seenIn[0] = segment
		}
		prefix += v
		seenIn[prefix] = segment
	}
	fmt.Println(answer)
}
